# Interview bank: three practice loops shaped like a forward-deployed / solutions interview.
# Each loop has 4 rounds: scope a vague ask, debug code you did not write, a business SQL task, a design talk.
# Executed inside labs.py (py, sql, T exist). Expected values come from running the reference solution.
IV = []

def _ivp(title, task, fn, buggy, sol, calls, hint, prelude=None):
    ns = {}
    exec((prelude or "") + "\n" + sol, ns)
    tests = [T(l, e, repr(eval(e, ns))) for l, e in calls]
    d = py(title, task, buggy, sol, hint, tests, **(dict(prelude=prelude) if prelude else {}))
    d.update(bug=True, iv=True, day=99, area="pipe", round="debug", steps=["Read the docstring: it is the contract", "Run it and read which check fails", "Find the line that breaks the contract", "Fix one thing, run again"])
    IV.append(d)

def _ivs(title, task, solution, hint, ordered=False):
    d = sql(title, task, solution, hint, ordered)
    d.update(iv=True, day=99, area="sql", round="sql")
    IV.append(d)

def _ivd(rnd, title, task, questions, steps, trade, model, keys):
    IV.append(dict(kind="design", iv=True, day=99, area="scope", round=rnd, title=title, task=task, questions=[list(q) for q in questions],
                   steps=steps, trade=trade, model=model, keys=[list(k) for k in keys]))

