_ivp("Debug: the daily totals do not match the bank file",
 "<code>daily_totals</code> reads an export where each line is <code>date;amount</code>. Finance says the last day is always missing and the totals are too low. <b>Read the docstring, run the checks, fix the function.</b>",
 "daily_totals",
 "def daily_totals(lines):\n    \"\"\"lines: list of text lines. The first line is a header ('date;amount').\n    Each data line is 'YYYY-MM-DD;amount'. Amounts may contain thousands commas ('1,200.50')\n    and spaces around the parts. Blank lines are ignored and NOT counted as skipped.\n    A line that does not have exactly two parts, or whose amount is not a number,\n    is skipped and counted.\n    Return (totals, skipped): totals maps each date to its sum rounded to 2 decimals.\"\"\"\n    totals = {}\n    skipped = 0\n    for line in lines[1:len(lines) - 1]:\n        parts = line.split(';')\n        if len(parts) != 2:\n            skipped += 1\n            continue\n        day, amount = parts\n        try:\n            value = float(amount)\n        except ValueError:\n            skipped += 1\n            continue\n        totals[day] = totals.get(day, 0) + value\n    return totals, skipped\n",
 "def daily_totals(lines):\n    totals = {}\n    skipped = 0\n    for line in lines[1:]:\n        if not line.strip():\n            continue\n        parts = line.split(';')\n        if len(parts) != 2:\n            skipped += 1\n            continue\n        day, amount = parts[0].strip(), parts[1].strip().replace(',', '')\n        try:\n            value = float(amount)\n        except ValueError:\n            skipped += 1\n            continue\n        totals[day] = totals.get(day, 0) + value\n    return {d: round(v, 2) for d, v in totals.items()}, skipped\n",
 [("simple file", "daily_totals(['date;amount', '2026-03-01;10', '2026-03-01;5.5', '2026-03-02;7'])"), ("the last line counts", "daily_totals(['date;amount', '2026-03-01;10', '2026-03-09;99'])"), ("thousands commas are numbers", "daily_totals(['date;amount', '2026-03-01;1,200.50', '2026-03-01;2,000'])"), ("blank lines are ignored, not skipped", "daily_totals(['date;amount', '', '2026-03-01;4', '   ', '2026-03-02;6'])"), ("bad lines are skipped and counted", "daily_totals(['date;amount', '2026-03-01;abc', 'garbage', '2026-03-01;1;2', '2026-03-01;3'])"), ("spaces around parts", "daily_totals(['date;amount', ' 2026-03-01 ; 8 ', '2026-03-01;2'])"), ("totals are rounded", "daily_totals(['date;amount', '2026-03-01;0.1', '2026-03-01;0.2'])"), ("header only", "daily_totals(['date;amount'])")],
 "Check four things against the docstring: which lines the loop visits, blank lines, how the amount text is cleaned, and rounding.")

_ivs("SQL: what each manager's team costs",
 "The finance lead asks: <i>\"For each manager, how many people report to them directly and what does that team cost in salary? Count a missing salary as zero.\"</i> Return the manager's <code>name</code>, the number of direct reports and the total salary of those reports. Only people who have at least one direct report.",
 "SELECT m.name, COUNT(e.id), SUM(COALESCE(e.salary, 0)) FROM employees m JOIN employees e ON e.manager_id = m.id GROUP BY m.id, m.name",
 "Join employees to itself: one copy is the manager, the other the report. A team whose only salary is missing should total 0, not NULL.")

